// 1. ╨г╨║╨░╨╢╨╕ ╨╖╨┤╨╡╤Б╤М ID ╨┐╨╛╨╗╤М╨╖╨╛╨▓╨░╤В╨╡╨╗╨╡╨╣, ╨╛╤В ╨║╨╛╤В╨╛╤А╤Л╤Е ╨╜╤Г╨╢╨╜╨╛ ╨┐╤А╨╕╨╜╨╕╨╝╨░╤В╤М ╤Б╨╛╨╛╨▒╤Й╨╡╨╜╨╕╤П
const ALLOWED_IDS = [908572509, 190100700, 427307131, 
1438569462]; 

return items.map(item => {
  // ╨Ш╤Й╨╡╨╝ ╤Б╨╛╨╛╨▒╤Й╨╡╨╜╨╕╨╡ (╤Г╤З╨╕╤В╤Л╨▓╨░╨╡╨╝ ╨╛╨▒╤Л╤З╨╜╤Л╨╡ ╨╕ ╨▒╨╕╨╖╨╜╨╡╤Б-╤Б╨╛╨╛╨▒╤Й╨╡╨╜╨╕╤П)
  const src = item.json.body || item.json;
  const message = src.message || src.business_message || src.edited_message;

  if (!message || !message.from) return null;

  const userId = message.from.id;
  const fullText = message.text || message.caption || "";

  // 2. ╨Я╨а╨Ю╨Т╨Х╨а╨Ъ╨Р ID: ╨Х╤Б╨╗╨╕ ╨╛╤В╨┐╤А╨░╨▓╨╕╤В╨╡╨╗╤П ╨╜╨╡╤В ╨▓ ╤Б╨┐╨╕╤Б╨║╨╡ ╤А╨░╨╖╤А╨╡╤И╨╡╨╜╨╜╤Л╤Е тАФ ╨┐╤А╨╛╨┐╤Г╤Б╨║╨░╨╡╨╝
  if (!ALLOWED_IDS.includes(userId)) {
    return null;
  }

  // 3. ╨Я╨а╨Ю╨Т╨Х╨а╨Ъ╨Р ╨Э╨Р╨Ы╨Ш╨з╨Ш╨п ╨Ц╨Ш╨а╨Э╨Ю╨У╨Ю ╨в╨Х╨Ъ╨б╨в╨Р
  let topic = "";

  if (message.entities) {
    const boldEntities = message.entities.filter(entity => entity.type === 'bold');

    if (boldEntities.length > 0) {
      topic = boldEntities
        .map(entity => fullText.substring(entity.offset, entity.offset + entity.length))
        .join(' ')
        .trim();
    }
  }

  // ╨Х╤Б╨╗╨╕ ╨╢╨╕╤А╨╜╤Л╨╣ ╤В╨╡╨║╤Б╤В ╨╜╨╡ ╨╜╨░╨╣╨┤╨╡╨╜ тАФ ╨┐╤А╨╛╨┐╤Г╤Б╨║╨░╨╡╨╝ ╤Б╨╛╨╛╨▒╤Й╨╡╨╜╨╕╨╡ ╤Ж╨╡╨╗╨╕╨║╨╛╨╝
  if (!topic) {
    return null;
  }

  // 4. ╨Т╨Ю╨Ч╨Т╨а╨Р╨й╨Р╨Х╨Ь ╨а╨Х╨Ч╨г╨Ы╨м╨в╨Р╨в
  return {
    json: {
      user_id: userId,
      name: `${message.from.first_name || ''} ${message.from.last_name || ''}`.trim(),
      username: message.from.username,
      extracted_topic: topic,
      full_text: fullText,
      biz_connection_id: message.business_connection_id || null
    }
  };
})
// ╨Ю╤З╨╕╤Б╤В╨║╨░ ╨╝╨░╤Б╤Б╨╕╨▓╨░ ╨╛╤В null ╤А╨╡╨╖╤Г╨╗╤М╤В╨░╤В╨╛╨▓
.filter(item => item !== null);
